/* ---------------- 改善檔案自動匯入 ----------------
 * 來源資料夾（指令碼屬性 IMP_SRC_FOLDER，例如「農部查核資料COPY」）每天自動掃描：
 *   新檔案依檔名（日期_單位_工程名稱…）對應案件；唯一對應者自動複製到「督導改善檔案」並登記為改善檔案，
 *   對應不到或有多個候選者列入「改善來源」表待人工對應（管理頁「改善檔案自動匯入」）。
 * 來源檔案不搬動、不改名；同一來源檔只處理一次。
 */
const IMP_SRC_COLS = ['來源ID', '檔名', '路徑', '大小', '修改時間', '狀態', '案件編號', '候選', '系統檔案ID', '說明', '處理時間'];
function impKey_(s) { return String(s || '').normalize('NFKC').replace(/臺/g, '台').replace(/[^\p{L}\p{N}]/gu, ''); }
/** 遞迴列出來源資料夾的檔案（略過 Google 文件類型） */
function impSrcFiles_(folderId, path, out, depth) {
  out = out || []; depth = depth || 0;
  let token = '';
  do {
    const q = encodeURIComponent("'" + folderId + "' in parents and trashed=false");
    const r = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files?q=' + q + '&fields=nextPageToken,files(id,name,mimeType,size,modifiedTime)&pageSize=1000&supportsAllDrives=true&includeItemsFromAllDrives=true' + (token ? '&pageToken=' + token : '')).getContentText());
    (r.files || []).forEach(f => {
      if (f.mimeType === 'application/vnd.google-apps.folder') { if (depth < 4) impSrcFiles_(f.id, (path ? path + '/' : '') + f.name, out, depth + 1); }
      else if (!/^application\/vnd\.google-apps\./.test(f.mimeType) && !/^desktop\.ini$/i.test(f.name)) out.push({ id: f.id, name: f.name, path: path || '', size: +(f.size || 0), modifiedTime: f.modifiedTime || '', mimeType: f.mimeType });
    });
    token = r.nextPageToken || '';
  } while (token);
  return out;
}
/** 依檔名找候選案件：工程名稱出現在檔名中；多筆時以檔名開頭日期（yyyymmdd）、查核類優先篩選 */
function impMatch_(f, cases) {
  const base = f.name.replace(/\.[^.]+$/, ''), fk = impKey_(base + ' ' + f.path);
  const dm = (base + ' ' + f.path).match(/(20\d{2})(\d{2})(\d{2})/), d = dm ? dm[1] + '-' + dm[2] + '-' + dm[3] : '';
  let hit = cases.filter(c => { const k = impKey_(c.工程名稱); return k.length >= 4 && fk.indexOf(k) >= 0; });
  if (hit.length > 1) { const L = Math.max.apply(null, hit.map(c => impKey_(c.工程名稱).length)); const longest = hit.filter(c => impKey_(c.工程名稱).length === L); if (longest.length < hit.length && longest.length >= 1) hit = longest; }
  if (hit.length > 1 && d) { const sameDay = hit.filter(c => c.日期 === d); if (sameDay.length) hit = sameDay; }
  if (hit.length > 1) { const q = hit.filter(c => /查核/.test(c.項目)); if (q.length) hit = q; }
  if (hit.length > 1) { const yr = rocYear_(ymd_(new Date())); const cur = hit.filter(c => String(c.年度) === String(yr)); if (cur.length) hit = cur; }
  return hit;
}
/** 掃描來源資料夾：自動匯入唯一對應者；args.dryRun 只回報 */
function apiImpScan(args, user) {
  const folder = prop_('IMP_SRC_FOLDER', '');
  if (!folder) throw new Error('尚未設定改善檔案來源資料夾');
  ensureCols_('紀錄檔', ['種類']);
  const sh = sheet_('改善來源');
  const seen = {}; readTable_('改善來源').forEach(r => { seen[r.來源ID] = r; });
  const cases = readTable_('案件').filter(c => c.狀態 !== ST_CANCEL && c.狀態 !== ST_VOID && c.日期);
  const files = impSrcFiles_(folder, '');
  const now = nowStr_(), rows = [], rep = { total: files.length, newFiles: 0, auto: 0, pending: 0, auto_list: [], pending_list: [] };
  const t0 = Date.now();
  files.forEach(f => {
    if (seen[f.id] || Date.now() - t0 > 240000) return;
    rep.newFiles++;
    const hit = impMatch_(f, cases);
    const row = { 來源ID: f.id, 檔名: f.name, 路徑: f.path, 大小: f.size, 修改時間: f.modifiedTime, 狀態: '待對應', 案件編號: '', 候選: hit.slice(0, 5).map(c => c.案件編號).join(','), 系統檔案ID: '', 說明: hit.length ? (hit.length > 1 ? '多個候選案件' : '') : '找不到對應案件', 處理時間: now };
    if (hit.length === 1 && !args.dryRun) {
      try { const r = impCopy_(f, hit[0], user || { Email: 'auto' }, now); Object.assign(row, { 狀態: '已匯入', 案件編號: hit[0].案件編號, 系統檔案ID: r.id, 說明: r.name }); rep.auto++; rep.auto_list.push(hit[0].案件編號 + ' ' + f.name); }
      catch (e) { row.說明 = '複製失敗：' + e.message; rep.pending++; rep.pending_list.push(f.name); }
    } else { rep.pending++; rep.pending_list.push(f.name + (hit.length ? '（' + row.候選 + '）' : '')); }
    rows.push(row);
  });
  if (!args.dryRun && rows.length) appendRows_('改善來源', rows);
  setProp_('IMP_SCAN_INFO', JSON.stringify({ time: now, total: files.length, auto: rep.auto, pending: rep.pending }));
  if (!args.dryRun && rep.auto) log_(user ? user.Email : 'auto', '改善檔案自動匯入', '', { 匯入: rep.auto, 待對應: rep.pending });
  return rep;
}
/** 由來源檔複製一份到「督導改善檔案」，統一檔名並登記 */
function impCopy_(f, c, user, now) {
  const n = findRows_('紀錄檔', '案件編號', c.案件編號).filter(x => x.種類 === IMP_KIND).length;
  const base = recFileName_(c, f.name).replace(/_(督導|查核)紀錄_/, '_' + IMP_KIND + '_');
  const name = n ? base.replace(/(\.[A-Za-z0-9]{2,5})?$/, m => '_' + (n + 1) + m) : base;
  const cp = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + f.id + '/copy?fields=id,size,mimeType&supportsAllDrives=true', {
    method: 'post', contentType: 'application/json', payload: JSON.stringify({ name: name, parents: [impFolder_()] }) }).getContentText());
  appendRows_('紀錄檔', [{ 案件編號: c.案件編號, 檔名: name, 類型: cp.mimeType || f.mimeType || '', 檔案ID: cp.id, 大小: +(cp.size || f.size || 0), 上傳者: user.Email, 上傳時間: now, 種類: IMP_KIND }]);
  return { id: cp.id, name: name };
}
/** 待對應清單（含候選案件資訊） */
function apiImpPending() {
  const C = {}; readTable_('案件').forEach(c => { C[c.案件編號] = c; });
  const info = (() => { try { return JSON.parse(prop_('IMP_SCAN_INFO', '') || 'null'); } catch (e) { return null; } })();
  return {
    folder: prop_('IMP_SRC_FOLDER', ''), auto: !!ScriptApp.getProjectTriggers().find(t => t.getHandlerFunction() === 'impScanJob'), info: info,
    items: readTable_('改善來源').filter(r => r.狀態 === '待對應').map(r => ({ 來源ID: String(r.來源ID), 檔名: String(r.檔名), 路徑: String(r.路徑 || ''), 修改時間: String(r.修改時間 || ''), 說明: String(r.說明 || ''),
      候選: String(r.候選 || '').split(',').filter(Boolean).map(id => C[id] ? { id: id, 日期: String(C[id].日期 || ''), 項目: String(C[id].項目 || ''), 單位: String(C[id].單位 || ''), 工程名稱: String(C[id].工程名稱 || '') } : null).filter(Boolean) })),
    recent: readTable_('改善來源').filter(r => r.狀態 === '已匯入').slice(-30).reverse().map(r => ({ 檔名: String(r.檔名), 案件編號: String(r.案件編號), 處理時間: String(r.處理時間 || '') }))
  };
}
/** 人工對應：args = {srcId, caseId}；或 {srcId, skip:true} 略過 */
function apiImpAssign(args, user) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const r = findRows_('改善來源', '來源ID', String(args.srcId || ''))[0];
    if (!r) throw new Error('找不到來源檔');
    if (r.狀態 === '已匯入') throw new Error('此檔已匯入（' + r.案件編號 + '）');
    const now = nowStr_();
    if (args.skip) { r.狀態 = '略過'; r.說明 = '人工略過'; r.處理時間 = now; writeRow_('改善來源', r); return { ok: true }; }
    const c = findRows_('案件', '案件編號', String(args.caseId || ''))[0];
    if (!c) throw new Error('找不到案件 ' + args.caseId);
    const res = impCopy_({ id: r.來源ID, name: r.檔名, mimeType: '', size: r.大小 }, c, user, now);
    Object.assign(r, { 狀態: '已匯入', 案件編號: c.案件編號, 系統檔案ID: res.id, 說明: res.name, 處理時間: now }); writeRow_('改善來源', r);
    log_(user.Email, '改善檔案對應匯入', c.案件編號, { 來源: r.檔名, 檔名: res.name });
    return { ok: true, name: res.name };
  } finally { lock.releaseLock(); }
}
/** 設定來源資料夾與每日自動掃描（限擁有者） */
function apiImpSetup(args, user) {
  if (String(user.Email).toLowerCase() !== String(prop_('OWNER_EMAIL', DEFAULT_OWNER)).toLowerCase()) throw new Error('限系統擁有者');
  const m = String(args.folder || '').match(/[-\w]{20,}/);
  if (args.folder !== undefined) { if (!m) throw new Error('資料夾網址或 ID 不正確'); setProp_('IMP_SRC_FOLDER', m[0]); }
  ScriptApp.getProjectTriggers().filter(t => t.getHandlerFunction() === 'impScanJob').forEach(t => ScriptApp.deleteTrigger(t));
  if (args.auto) ScriptApp.newTrigger('impScanJob').timeBased().everyDays(1).atHour(7).create();
  return apiImpPending();
}
/** 每日排程（以擁有者身分執行） */
function impScanJob() { apiImpScan({}, { Email: 'auto' }); }
